/* app_user.c — YOUR application lives here.
 *
 * This is a user file: nothing under App/ is ever regenerated by CubeMX, so your code is safe.
 *
 * The file is deliberately split into three parts:
 *   1. CONFIGURATION TABLES — describe your hardware here. This is normally all you edit.
 *   2. YOUR CONTROL LOGIC   — your application tasks.
 *   3. STARTUP              — generic wiring; you rarely need to touch it.
 *
 * Platform services are in app_platform.h:
 *   - Process-image I/O (cyclic, non-blocking):  app_io_setup() then app_io_di/ai/do_set/hr_set()
 *   - Onboard high-speed inputs (CN4):           app_hsdi_setup() then app_hsdi_level/count/...
 *   - On-demand Modbus master (blocking):        app_mb_read_holding/read_input/write_single/...
 *   - Backplane expansion modules:               any of the above, port = APP_PORT_BACKPLANE
 *   - Time / temperature / buzzer:               app_time_now() / app_temp_read() / app_beep_set()
 *   - Power-fail retained variables:             mark them PF_RETAIN (see app_pwrfail.h)
 */
