/* ---- 1a. Field devices polled over Modbus (the process-image scan table) ----
 * Three devices on the 485A port. The CM4 scanner polls them in the background and keeps their
 * data in the process image; your code and any external master then just read/write memory.
 *   addr 1 : 12 digital inputs + 8 digital outputs
 *   addr 2 : 8 x 16-bit analog inputs
 *   addr 3 : 8 x 16-bit analog outputs
 * `start` = the address inside that device (from its manual). `period` = poll interval in base
 * ticks (1 tick = 1 ms).
 *
 * PICK PERIODS THAT MATCH THE PHYSICS, not the fastest the bus allows. A relay does not need
 * a 1 ms refresh — asking for one just saturates the bus (its TX LED goes solid) and starves
 * every other module. 20 ms for digital, 50..100 ms for relays and analog is plenty; this is
 * also how you budget bus bandwidth between modules. */
static app_io_point_t s_io_table[] = {   /* size comes from the rows below, so the check is real
                                          * (RAM: the bench `pulse` command shortens the relay period) */
  /* port,          addr, access,             flags, start, count, period */
  { APP_PORT_485A,  1,    APP_IO_IN_DISCRETE, 0,     0,     12,    20  },  /* PT_DI: 12 DI  <- FC02 */
  { APP_PORT_485A,  2,    APP_IO_IN_INPUT_REG,0,     0,     8,     100 },  /* PT_AI:  8 AI  <- FC04 */
  { APP_PORT_485A,  1,    APP_IO_OUT_COILS,   0,     0,     8,     20  },  /* PT_DO:  8 DO  -> FC15 */
  { APP_PORT_485A,  3,    APP_IO_OUT_HOLDING, 0,     0,     8,     100 },  /* PT_AO:  8 AO  -> FC16 */
  /* A 16-channel relay module on the internal backplane at DIP address 2. The backplane is
   * plain Modbus, so it is just two more rows: one to drive the relays, one to read their real
   * state back (FC01) rather than trusting the commanded value. */
  { APP_PORT_BACKPLANE, 2, APP_IO_OUT_COILS,   0,     0,     16,    50  },  /* PT_RELAY:    drive 16 relays */
  { APP_PORT_BACKPLANE, 2, APP_IO_IN_COILS,    0,     0,     16,    100 },  /* PT_RELAY_RB: true read-back */
  /* PH_EC engineering block (module spec §2, 0x0108: ph1,ph2,ec1,ec2,t1..t4 x0.1/0.01):
   * the vent controller (app_vent.c) reads air temperature t2 from here. 1 s is plenty
   * for a thermal process and costs the backplane next to nothing. */
  { APP_PORT_BACKPLANE, 4, APP_IO_IN_INPUT_REG,0,     0x0108,8,     1000 }, /* PT_PHEC: pH/EC/temps */
};
/* Add a row above and a name in app_user_points.h, in the same order — this catches forgetting
 * either side at build time instead of silently addressing the wrong point at run time. */
_Static_assert(sizeof(s_io_table) / sizeof(s_io_table[0]) == PT_COUNT,
               "s_io_table and the point names in app_user_points.h are out of sync");

/* The "input edge toggles a relay" demo is GONE (2026-09-03): HSDI4~7 now carry the four
 * gutter level sensors and HSDI0 the water meter -- on this installation no onboard input
 * may ever drive an output. (Its CM4 twin, HSDI1 -> relay 12 in app_user_cm4.c, was retired
 * the same day.) Inputs are read below and published; the control logic decides. */

/* ---- 1b. Onboard high-speed digital inputs (the 8 channels on CN4) ----
 * As shipped: SEVEN pulse counters + one plain input (2026-09-01: one pulse flow meter per
 * irrigation line — a clogged line shows up as a stalled counter). Hardware counters sit on
 * HSDI0/4/6, the only channels that can clock their timer (TIM3 / TIM1 / TIM8, one counter
 * per timer); HSDI1/2/3/5 count in software (EXTI edges, fine for <=10 kHz pulse sensors,
 * debounce 0 because a hall flow sensor is an electronic signal). HSDI7 stays a plain input:
 * it shares EXTI0 with HSDI2 and only one of that pair may count — seven counters is this
 * board's silicon ceiling.
 *
 * For two quadrature encoders instead, change the rows to:
 *   HSDI0 = ENC_A, HSDI1 = ENC_B, HSDI2 = ENC_Z   -> encoder 0 (TIM3)
 *   HSDI4 = ENC_A, HSDI5 = ENC_B, HSDI3 = ENC_Z   -> encoder 1 (TIM1)
 *   HSDI6 = COUNT_HW, HSDI7 = COUNT_SW
 * Two encoders AND three hardware counters is not possible — the encoders consume TIM3 and
 * TIM1, leaving only TIM8. An unrealisable table is rejected at startup and every channel
 * falls back to a plain input. Full combination table: HSDI_Configuration_and_Counting.md */
static app_hsdi_ch_t s_hsdi_table[8] = {   /* RAM copy: `hsdi <ch> <mode> ...` re-modes a channel at run time (bench) */
  /* mode,               filter, edge,                 z_action, debounce_ms, min_us */
  { APP_HSDI_COUNT_CAP,  15, APP_HSDI_EDGE_RISING,  0,        0,  1000 },  /* HSDI0  water meter: same hall type as the gutter meters,
                                                                           * same treatment (was a TIM3 hardware counter, filter 4) */
  { APP_HSDI_DI,         0,  0,                     0,        10, 0    },  /* HSDI1  spare (PC7) */
  { APP_HSDI_DI,         0,  0,                     0,        10, 0    },  /* HSDI2  spare (PB0) */
  { APP_HSDI_DI,         0,  0,                     0,        10, 0    },  /* HSDI3  spare (PB1) */
  /* HSDI4~7 = per-gutter hall flow meters 1~4 (2026-09-03, 1200 p/L; terminals 2/4, 7/9, 8/10, 12/14).
   * Capture counters with the pulse qualifier (2026-09-04): both edges are timestamped in the
   * timer capture interrupt and a level counts only after it has held min_us = 1000 us. The
   * 15 ms meter pulses carry microsecond dips that made every plain edge method (EXTI, ICF15
   * capture, timer external clock) read 1.5..2x; the qualifier reads what 1 kHz sampling and
   * the measuring jug read (1.4/1.5/1.3/1.5 L/min, 2026-09-04). What the edge recorder
   * found the same day: the dirt is ~97 kHz oscillation bursts (edges 5 us apart, 1..8 ms
   * long) on the gutter-2 line, plus the sub-microsecond blips it couples into the other
   * three lines. filter 15 (~1 us) removes the blips, min_us drops the bursts, the storm
   * breaker bounds the interrupt load. min_us 3000: a 21 s recording showed chatter phases
   * up to 925 us, too close to 1000; a gutter runs ~30 Hz (16 ms phases), 3000 still allows
   * 166 Hz = 8 L/min. The 1 kHz sampler over-counts those 0.5..1 ms glitches by 1..3 %,
   * so cnt slightly below poll in `hsdi <ch> stat` is the qualifier being right.
   * No EXTI line is used, so HSDI7 no longer collides with HSDI2 on EXTI0. */
  { APP_HSDI_COUNT_CAP,  15, APP_HSDI_EDGE_RISING,  0,        0,  3000 },  /* HSDI4  gutter 1 flow (TIM1_CH1) */
  { APP_HSDI_COUNT_CAP,  15, APP_HSDI_EDGE_RISING,  0,        0,  3000 },  /* HSDI5  gutter 2 flow (TIM1_CH2, terminals 7/9) */
  { APP_HSDI_COUNT_CAP,  15, APP_HSDI_EDGE_RISING,  0,        0,  3000 },  /* HSDI6  gutter 3 flow (TIM8_CH2) */
  { APP_HSDI_COUNT_CAP,  15, APP_HSDI_EDGE_RISING,  0,        0,  3000 },  /* HSDI7  gutter 4 flow (TIM8_CH3) */
};

